"""Pydantic schema for Gemini Vision structured output validation.

This module defines the schema used to validate metadata returned by Gemini Vision.
It ensures that every image response contains required fields and that the confidence
score strictly falls between 0.0 and 1.0.
"""

from pydantic import BaseModel, Field, field_validator


class ImageMetadataSchema(BaseModel):
    """Structured image metadata generated by Gemini Vision.

    Fields:
    - subject: Main subject in the image (e.g. 'red fox', 'wolf', 'dog')
    - category: General category (e.g. 'wildlife', 'domestic', 'nature')
    - attributes: List of visual features observed in the image
    - caption: A concise summary caption of the image content
    - confidence: Confidence score from 0.0 to 1.0
    """

    subject: str = Field(description="The main subject of the image")
    category: str = Field(description="The general category of the image")
    attributes: list[str] = Field(description="Visual attributes seen in the image")
    caption: str = Field(description="Concise caption summarizing the image")
    confidence: float = Field(description="Confidence score between 0.0 and 1.0")

    @field_validator("confidence")
    @classmethod
    def validate_confidence_range(cls, value: float) -> float:
        """Ensure confidence score is strictly between 0.0 and 1.0."""
        if value < 0.0 or value > 1.0:
            raise ValueError(f"Confidence score must be between 0.0 and 1.0, got {value}")
        return value
